user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "IS_STATE_AUDIT_PLAN",
    "definition": "The reasoning enumerates a set of distinct, concrete system-state conditions that must be confirmed before the task may be declared complete, functioning as a verification checklist rather than as a list of changes to make.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text enumerating the state conditions to be confirmed."
      }
    ],
    "assertion_conditions": [
      "The reasoning lists two or more distinct conditions, artifacts, or behaviors to be checked in the current system state.",
      "The listed items are framed as things to confirm or observe, not as actions that modify the system.",
      "At least one item includes an anticipated or acceptance value against which a later observation can be compared."
    ],
    "exclusion_conditions": [
      "The reasoning describes a single check without forming a multi-item verification set.",
      "The reasoning lists only modification steps (install, write, configure) with no confirmation criteria.",
      "The reasoning merely restates results already observed without enumerating conditions still to be confirmed."
    ]
  },
  {
    "name": "AUDITS_PLANNED_CRITERIA",
    "definition": "An action collects current state for the specific conditions enumerated in a prior verification plan, and its result reports values or artifacts for those conditions, so that each planned criterion can be checked against the returned state.",
    "parameters": [
      {
        "name": "plan_reasoning",
        "type": "reasoning",
        "description": "The reasoning enumerating the criteria to be verified."
      },
      {
        "name": "audit_action",
        "type": "action",
        "description": "The action that gathers the corresponding system state, possibly several checks in one invocation."
      },
      {
        "name": "audit_result",
        "type": "observation",
        "description": "The observation reporting the values or artifacts for the planned criteria."
      }
    ],
    "assertion_conditions": [
      "The plan_reasoning enumerates specific conditions to be confirmed.",
      "The audit_action inspects the aspects of the system that correspond to those conditions.",
      "The audit_result contains identifiable values for the planned criteria, sufficient to judge each one."
    ],
    "exclusion_conditions": [
      "The action probes aspects unrelated to the enumerated criteria.",
      "The observation does not report values for the planned criteria.",
      "No prior criteria were enumerated, so the action is exploratory rather than an audit of a plan."
    ]
  },
  {
    "name": "REPLAYS_STIPULATED_USAGE_AS_ACCEPTANCE_TEST",
    "definition": "The reasoning commits to reproducing the exact usage sequence or commands stipulated by the requester, and the action executes that sequence so that a pass demonstrates the stipulated workflow itself works.",
    "parameters": [
      {
        "name": "test_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating that the requester's own documented sequence will be reproduced as the test."
      },
      {
        "name": "replay_action",
        "type": "action",
        "description": "The action executing that stipulated sequence."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly states that the check will mirror the requester's own documented commands or workflow.",
      "The action performs that sequence rather than an internal proxy or a reduced subset."
    ],
    "exclusion_conditions": [
      "The action tests an alternative or partial implementation of the workflow instead of the stipulated one.",
      "The reasoning only describes expected behavior without committing to replaying the requester's sequence.",
      "The action exercises components individually in a way the requester would not."
    ]
  },
  {
    "name": "CONFIRMS_REQUIREMENT_SATISFACTION",
    "definition": "The reasoning concludes that a stipulated acceptance requirement is satisfied because the observation exhibits exactly the behavior that requirement demands.",
    "parameters": [
      {
        "name": "conclusion_reasoning",
        "type": "reasoning",
        "description": "The agent text asserting that the acceptance requirement is met."
      },
      {
        "name": "result_observation",
        "type": "observation",
        "description": "The observation exhibiting the stipulated end behavior."
      }
    ],
    "assertion_conditions": [
      "The reasoning asserts that a previously stated acceptance requirement or desired end behavior is met.",
      "The observation reports the stipulated behavior itself (expected content, status, or result) rather than an intermediate side effect."
    ],
    "exclusion_conditions": [
      "The reasoning only reports that a command executed without asserting requirement satisfaction.",
      "The observation shows a different, partial, or unexpected behavior.",
      "The reasoning asserts success before the corresponding observation exists."
    ]
  },
  {
    "name": "EXPLAINS_RESULT_AS_PROBE_ARTIFACT",
    "definition": "The reasoning attributes an unexpected, empty, or negative result to a limitation or behavior of the measurement technique itself, rather than to the state of the system being inspected.",
    "parameters": [
      {
        "name": "diagnostic_reasoning",
        "type": "reasoning",
        "description": "The agent text identifying the methodological cause of the unexpected result."
      },
      {
        "name": "anomalous_observation",
        "type": "observation",
        "description": "The observation reporting the unexpected, empty, or misleading result."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific property of the probe method (tool option, missing capability, encoding, non-recursion, buffering) that would produce the observed result regardless of the target state.",
      "The reasoning contrasts this methodological explanation with independent evidence that the target state is actually as intended."
    ],
    "exclusion_conditions": [
      "The reasoning treats the unexpected result as genuine evidence about the target system.",
      "No methodological cause for the result is identified.",
      "The reasoning merely repeats the null result without explaining it."
    ]
  },
  {
    "name": "ASSESSES_ANOMALY_AS_NON_IMPACTING",
    "definition": "The reasoning acknowledges that an anomaly reported in the observation is real but judges it inconsequential to the required functionality, grounding that judgment in independent evidence that the required function still succeeds.",
    "parameters": [
      {
        "name": "assessment_reasoning",
        "type": "reasoning",
        "description": "The agent text evaluating the significance of the observed anomaly."
      },
      {
        "name": "anomaly_observation",
        "type": "observation",
        "description": "The observation reporting the anomaly (unexpected process state, leftover connection state, stray artifacts)."
      }
    ],
    "assertion_conditions": [
      "The reasoning names the observed anomaly and states explicitly that it does not affect the required behavior.",
      "The judgment is supported by independent functional evidence (a successful operation that exercises the same subsystem) rather than by assertion alone."
    ],
    "exclusion_conditions": [
      "The anomaly is dismissed without any explanation or supporting functional evidence.",
      "The reasoning treats the anomaly as a blocking problem that must be eliminated.",
      "The anomaly actually prevents or degrades the required functionality."
    ]
  },
  {
    "name": "DECODES_ENCODED_OBSERVATION",
    "definition": "The reasoning translates low-level or encoded fields returned by an observation (numeric state codes, hexadecimal addresses, raw tables, machine-oriented formats) into domain-level states, and the stated conclusion depends on that translation.",
    "parameters": [
      {
        "name": "interpretation_reasoning",
        "type": "reasoning",
        "description": "The agent text mapping raw fields to domain-level meanings."
      },
      {
        "name": "encoded_observation",
        "type": "observation",
        "description": "The observation whose content is in an encoded or machine-oriented form."
      }
    ],
    "assertion_conditions": [
      "The observation content is not stated in plain domain terms (codes, hex, tabular raw fields).",
      "The reasoning explicitly maps the encoded values to concrete domain states and derives its conclusion from that mapping."
    ],
    "exclusion_conditions": [
      "The observation already reports the state in plain semantic terms.",
      "The reasoning restates raw content without mapping it to domain meanings.",
      "The reasoning's conclusion does not depend on the decoded fields."
    ]
  },
  {
    "name": "REINVESTIGATES_SUSPECT_RESULT",
    "definition": "The reasoning flags a check as inconclusive, empty, or suspicious, and the action re-examines the same underlying question using a different technique or source of evidence.",
    "parameters": [
      {
        "name": "doubt_reasoning",
        "type": "reasoning",
        "description": "The agent text expressing doubt about a prior or current result and the need to re-check."
      },
      {
        "name": "recheck_action",
        "type": "action",
        "description": "The action that re-examines the same question by alternative means."
      }
    ],
    "assertion_conditions": [
      "The reasoning expresses doubt, inconclusiveness, or suspicion about an existing result.",
      "The action addresses the same underlying question, using a different method, source, or tool than the earlier attempt."
    ],
    "exclusion_conditions": [
      "The action investigates a new question rather than the doubted result.",
      "No doubt or inconclusiveness about an existing result is expressed.",
      "The action simply repeats the identical probe that already produced the suspect result without changing technique."
    ]
  },
  {
    "name": "RESTORES_BASELINE_STATE",
    "definition": "The action removes or reverts artifacts created during testing so the system returns to its pre-test condition, and the reasoning states that the purpose is to leave a pristine starting point for the requester's own use.",
    "parameters": [
      {
        "name": "restore_action",
        "type": "action",
        "description": "The action deleting or reverting test-created artifacts."
      },
      {
        "name": "restore_reasoning",
        "type": "reasoning",
        "description": "The agent text stating the intent to return the system to its initial state."
      }
    ],
    "assertion_conditions": [
      "The action deletes, empties, or reverts state that was produced by the agent's own testing.",
      "The reasoning states that the goal is a clean/initial state so the requester's intended flow will work without interference."
    ],
    "exclusion_conditions": [
      "The action modifies state for a purpose other than reverting to the pre-test condition.",
      "The reasoning only notes that cleanup finished without stating the pristine-state intent.",
      "The action removes artifacts but leaves the system in a state that still blocks the requester's flow."
    ]
  },
  {
    "name": "IMPLEMENTS_PREVENTIVE_SAFEGUARD",
    "definition": "In response to reasoning that a required capability may later become unavailable, the action installs an additive fallback or auto-recovery mechanism that restores the capability without user intervention, beyond the minimum needed for the task.",
    "parameters": [
      {
        "name": "anticipation_reasoning",
        "type": "reasoning",
        "description": "The agent text identifying a possible future failure of a required capability."
      },
      {
        "name": "safeguard_action",
        "type": "action",
        "description": "The action creating the fallback or recovery mechanism."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a possible future failure or restart scenario for a required capability.",
      "The action creates a mechanism whose purpose is to re-establish or preserve that capability automatically, rather than performing the capability once.",
      "The mechanism is added robustness that exceeds the minimum required configuration."
    ],
    "exclusion_conditions": [
      "The action directly performs the required operation instead of preparing a recovery mechanism.",
      "No possible future failure or restart scenario is expressed in the reasoning.",
      "The action only documents or reports the capability without enabling its recovery."
    ]
  },
  {
    "name": "SUMMARIZES_COMPLETED_TASK",
    "definition": "The reasoning consolidates multiple completed and verified results into a completion report and declares that the task is finished.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text presenting the consolidated completion report."
      }
    ],
    "assertion_conditions": [
      "The reasoning reports several distinct results that were produced and verified during the run.",
      "The reasoning explicitly declares the task finished or complete."
    ],
    "exclusion_conditions": [
      "The reasoning is a plan for future actions rather than a report of completed work.",
      "The reasoning covers a single result without consolidating the outcome.",
      "The reasoning leaves the task open or requests further input."
    ]
  }
]

Existing registry:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses at least one intended future action or sequence of actions to be taken in service of the task.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing an intended future action or plan."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one operation or sequence of operations that the agent intends to perform later.",
      "The intended action is presented as something to be done, not merely as a completed observation or factual statement."
    ],
    "exclusion_conditions": [
      "The reasoning only reports actions that have already been completed.",
      "The reasoning states a fact or diagnosis without expressing any intended future action."
    ]
  },
  {
    "name": "ACTION_IMPLEMENTS_PLANNED_STEP",
    "definition": "A recorded action carries out an operation that a reasoning node explicitly proposed as a future step, with matching task purpose rather than merely topical or temporal adjacency.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The recorded tool invocation that performs the step."
      },
      {
        "name": "plan_reasoning",
        "type": "reasoning",
        "description": "The reasoning node that proposes the future operation."
      }
    ],
    "assertion_conditions": [
      "The plan_reasoning expresses an intended future operation or set of operations.",
      "The action performs an operation consistent with the purpose and target of the proposed step."
    ],
    "exclusion_conditions": [
      "The reasoning only describes past or completed actions.",
      "The action is unrelated to the proposed step or serves a different purpose.",
      "The connection is based only on temporal adjacency without matching intent."
    ]
  },
  {
    "name": "DIAGNOSES_OBSERVED_ARTIFACT_DEFECT",
    "definition": "The reasoning interprets content of an artifact exposed in an observation and identifies a specific missing, incomplete, or erroneous element that must be repaired.",
    "parameters": [
      {
        "name": "diagnosis_reasoning",
        "type": "reasoning",
        "description": "The reasoning that identifies the artifact defect or incompleteness."
      },
      {
        "name": "artifact_observation",
        "type": "observation",
        "description": "The observation exposing the artifact content being diagnosed."
      }
    ],
    "assertion_conditions": [
      "The observation exposes identifiable content of an artifact.",
      "The reasoning identifies a specific defect, gap, or incomplete element in that artifact relative to the intended requirement."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats or paraphrases the artifact content without identifying a defect.",
      "No specific missing, incomplete, or erroneous element is identified.",
      "The observation does not expose artifact content relevant to the diagnosis."
    ]
  },
  {
    "name": "PROPOSES_ARTIFACT_REPAIR",
    "definition": "The reasoning specifies a concrete correction or completion for an observed artifact defect, including replacement content or steps intended to make the artifact satisfy the requirement.",
    "parameters": [
      {
        "name": "repair_reasoning",
        "type": "reasoning",
        "description": "The reasoning containing the proposed repair or completion."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least one concrete change, replacement, or added step intended to repair or complete an artifact.",
      "The proposed repair is tied to an identified defect or requirement rather than being a generic intention to fix something."
    ],
    "exclusion_conditions": [
      "The reasoning only identifies a defect without proposing how to repair it.",
      "The reasoning expresses only a generic intention to fix or improve without concrete content or steps."
    ]
  },
  {
    "name": "CHECKS_ENVIRONMENT_PREREQUISITE",
    "definition": "An action probes the execution environment for the availability, identity, or version of a prerequisite tool or resource, and its observation reports capability evidence.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The diagnostic action that queries the environment or tool availability."
      },
      {
        "name": "probe_observation",
        "type": "observation",
        "description": "The observation reporting the presence, absence, identity, or version of the prerequisite."
      }
    ],
    "assertion_conditions": [
      "The action is a diagnostic query about a prerequisite needed for the task.",
      "The observation reports capability evidence such as presence, availability, identity, or version of the queried prerequisite."
    ],
    "exclusion_conditions": [
      "The action performs the primary task rather than checking a prerequisite.",
      "The observation does not report any information about prerequisite capability or availability."
    ]
  },
  {
    "name": "IMPLEMENTS_PROPOSED_REPAIR",
    "definition": "An action applies the concrete correction specified in repair reasoning to the target artifact, and its result observation confirms that the modification was accepted.",
    "parameters": [
      {
        "name": "repair_action",
        "type": "action",
        "description": "The action that writes or applies the proposed repair to the artifact."
      },
      {
        "name": "repair_reasoning",
        "type": "reasoning",
        "description": "The reasoning containing the concrete correction or completion to be applied."
      },
      {
        "name": "application_result",
        "type": "observation",
        "description": "The observation confirming whether the artifact modification was accepted."
      }
    ],
    "assertion_conditions": [
      "The repair_reasoning contains a concrete correction or completion for the artifact.",
      "The repair_action applies content or changes corresponding to that proposed repair to the target artifact.",
      "The application_result reports successful acceptance or modification of the artifact."
    ],
    "exclusion_conditions": [
      "The action is unrelated to the proposed repair.",
      "The content applied by the action does not correspond to the proposed correction.",
      "The result reports failure or does not confirm acceptance of the modification."
    ]
  },
  {
    "name": "PRODUCES_EXPECTED_BUILD_ARTIFACT",
    "definition": "An action invokes a build or compilation step on a source artifact, and its observation provides evidence that the expected derived artifact was generated.",
    "parameters": [
      {
        "name": "build_action",
        "type": "action",
        "description": "The action that runs the build or compilation process."
      },
      {
        "name": "build_observation",
        "type": "observation",
        "description": "The observation reporting generation of the expected derived artifact."
      }
    ],
    "assertion_conditions": [
      "The action invokes a build, compilation, or equivalent transformation of a source artifact.",
      "The observation provides evidence that the expected derived artifact was produced or exists after the build step."
    ],
    "exclusion_conditions": [
      "The action only inspects files without invoking a build or compilation step.",
      "The observation does not show that the expected derived artifact was generated.",
      "The build or compilation reports an error preventing artifact production."
    ]
  },
  {
    "name": "DIAGNOSES_ACTION_FAILURE_FROM_ERROR",
    "definition": "The reasoning interprets an error or non-success result reported by an observation and identifies the cause or the condition that a corrected attempt must satisfy.",
    "parameters": [
      {
        "name": "diagnosis_reasoning",
        "type": "reasoning",
        "description": "The reasoning that interprets the failure and identifies its cause or required correction."
      },
      {
        "name": "error_observation",
        "type": "observation",
        "description": "The observation reporting the error or non-success result."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error, nonzero exit, or otherwise unsuccessful result from a prior action.",
      "The reasoning identifies a cause, misunderstood condition, or requirement for a corrected attempt."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats the error message without interpreting its cause or implications.",
      "The reasoning retries the same operation without identifying any corrective condition.",
      "The observation does not report an error or failure."
    ]
  },
  {
    "name": "CORRECTS_FAILED_ACTION_WITH_DIAGNOSED_REVISION",
    "definition": "A subsequent action revises an earlier failed operation in accordance with an explicit diagnosis of the failure, rather than repeating the same operation unchanged.",
    "parameters": [
      {
        "name": "failed_action",
        "type": "action",
        "description": "The earlier action that produced the error result."
      },
      {
        "name": "error_observation",
        "type": "observation",
        "description": "The observation reporting the error from the failed action."
      },
      {
        "name": "correction_reasoning",
        "type": "reasoning",
        "description": "The reasoning that diagnoses the failure and indicates the needed revision."
      },
      {
        "name": "corrective_action",
        "type": "action",
        "description": "The subsequent action that implements the revised approach."
      }
    ],
    "assertion_conditions": [
      "The failed_action is associated with an error_observation reporting failure.",
      "The correction_reasoning identifies a cause or required change in approach.",
      "The corrective_action changes a relevant parameter, command, or method to address the diagnosed failure while pursuing the same goal."
    ],
    "exclusion_conditions": [
      "The subsequent action repeats the failed action identically without revision.",
      "The corrective action is unrelated to the diagnosed failure or targets a different goal.",
      "No error observation or explicit diagnosis supports the revision."
    ]
  },
  {
    "name": "VERIFIES_ARTIFACT_CONTENT_BY_INDEPENDENT_INSPECTION",
    "definition": "A targeted inspection or loading action retrieves the content of a produced artifact, and its observation exposes that content so the agent can confirm the artifact satisfies the intended property, not merely that it exists.",
    "parameters": [
      {
        "name": "verification_intent_reasoning",
        "type": "reasoning",
        "description": "The reasoning indicating the need or approach for checking artifact content."
      },
      {
        "name": "inspection_action",
        "type": "action",
        "description": "The action that loads or inspects the produced artifact's content."
      },
      {
        "name": "inspection_result",
        "type": "observation",
        "description": "The observation exposing the inspected artifact content or signature."
      }
    ],
    "assertion_conditions": [
      "The reasoning indicates a verification goal concerning the artifact's content or meaning.",
      "The inspection_action accesses or loads the produced artifact content rather than only checking file existence or metadata.",
      "The inspection_result exposes content consistent with the intended property being verified."
    ],
    "exclusion_conditions": [
      "The check only confirms file existence, size, or other metadata without exposing content.",
      "The observation output is unrelated to the intended property or is inconclusive.",
      "The inspection action fails or does not retrieve the artifact content."
    ]
  },
  {
    "name": "CONCLUDES_TASK_SUCCESS_FROM_ACCUMULATED_EVIDENCE",
    "definition": "The reasoning declares the task successfully completed and supports that declaration by referring to one or more observed verification outcomes rather than only restating the plan or action sequence.",
    "parameters": [
      {
        "name": "conclusion_reasoning",
        "type": "reasoning",
        "description": "The final reasoning that declares completion and cites verification evidence."
      },
      {
        "name": "supporting_observations",
        "type": "observation[]",
        "description": "The observations collectively supplying outcome evidence for the completion claim."
      }
    ],
    "assertion_conditions": [
      "The conclusion_reasoning asserts that the task has been successfully completed.",
      "The reasoning refers to or summarizes at least one observed outcome, such as a produced artifact or confirmed content.",
      "The supporting_observations collectively contain verification evidence rather than only action acknowledgments or plans."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates plans or intermediate actions without asserting completion.",
      "The success assertion is not supported by any observed outcome evidence.",
      "The cited observations are unrelated to the claimed completion."
    ]
  },
  {
    "name": "EVALUATES_ALTERNATIVES",
    "definition": "The reasoning contrasts two or more candidate approaches that could serve the same purpose and settles on one of them on the basis of an explicit comparative rationale.",
    "parameters": [
      {
        "name": "deliberating_reasoning",
        "type": "reasoning",
        "description": "The reasoning that contrasts candidate approaches and justifies the selected one."
      }
    ],
    "assertion_conditions": [
      "The reasoning names at least two candidate approaches, tools, or configuration choices that could serve the same purpose.",
      "The reasoning states a comparative rationale (robustness, availability, compatibility, convenience, simplicity) that favors the selected option over the alternative(s)."
    ],
    "exclusion_conditions": [
      "The reasoning describes only a single approach without contrasting it against another.",
      "The reasoning merely lists planned steps without weighing options against each other.",
      "Another option is mentioned only in passing without any selection between the options being made."
    ]
  },
  {
    "name": "IS_STATE_PROBE",
    "definition": "The action is a read-only inspection of system, environment, or artifact state carried out to obtain information, without altering that state.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action that inspects rather than modifies system or artifact state."
      }
    ],
    "assertion_conditions": [
      "The action consists of informational query or inspection operations, such as listing directories or processes, reading or dumping configuration, or querying package, user, or service state.",
      "The action's own description or command composition shows an informational purpose and contains no persistent modification of the inspected state."
    ],
    "exclusion_conditions": [
      "The action installs, creates, deletes, or reconfigures resources.",
      "An inspection command appears only incidentally inside an action whose purpose is a persistent change.",
      "The action executes a change and merely reports its own output."
    ]
  },
  {
    "name": "TESTS_ASSUMPTION_WITH_PROBE",
    "definition": "A targeted action is undertaken to discriminate a specific uncertainty or tentative assumption stated in reasoning, and its observation supplies evidence bearing on that assumption.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action performing the targeted test or inspection."
      },
      {
        "name": "assumption_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating the uncertainty or tentative assumption being tested."
      },
      {
        "name": "probe_observation",
        "type": "observation",
        "description": "The observation whose content addresses the stated uncertainty."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly formulates a specific uncertainty or tentative assumption about the environment, resources, or configuration.",
      "The action is chosen so that its result would distinguish between the assumption holding and not holding.",
      "The observation contains content interpretable as evidence for or against the stated assumption."
    ],
    "exclusion_conditions": [
      "No identifiable assumption or uncertainty motivates the inspection.",
      "The action inspects something unrelated to the stated assumption.",
      "The observation does not address the assumption being tested."
    ]
  },
  {
    "name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
    "definition": "The reasoning draws a conclusion about the system, environment, or task state using identifiable content of the observation as supporting evidence.",
    "parameters": [
      {
        "name": "concluding_reasoning",
        "type": "reasoning",
        "description": "The reasoning that states the evidence-based conclusion."
      },
      {
        "name": "evidential_observation",
        "type": "observation",
        "description": "The observation supplying the content that supports the conclusion."
      }
    ],
    "assertion_conditions": [
      "The reasoning asserts a conclusion about the state, capability, or composition of the environment or artifacts.",
      "Specific content of the observation (reported items, absent items, versions, statuses, fetched output) supports that conclusion."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates or paraphrases the observation without drawing an inference from it.",
      "The observation is unrelated to the stated conclusion or provides no identifiable support."
    ]
  },
  {
    "name": "ADAPTS_PLAN_TO_OBSERVED_STATE",
    "definition": "The reasoning revises the intended course of action in response to a state revealed by the observation that departs from the assumptions of the earlier plan or that constrains the available options.",
    "parameters": [
      {
        "name": "revised_plan_reasoning",
        "type": "reasoning",
        "description": "The reasoning that sets out the adjusted course of action."
      },
      {
        "name": "state_revealing_observation",
        "type": "observation",
        "description": "The observation that reveals the state prompting the adjustment."
      }
